@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  html {
    @apply bg-rhythm-obsidian text-rhythm-silver antialiased;
  }
  body {
    @apply bg-rhythm-obsidian text-rhythm-silver antialiased;
  }
  .glass {
    @apply bg-white/10 backdrop-blur-md border border-rhythm-goldenrod/20 rounded-lg;
  }
  .goldenrod {
    @apply bg-rhythm-goldenrod;
  }
  .white-glint {
    @apply text-rhythm-silver;
  }
}

/* Global CSS for Rhythm High Finance Nerve Center */

/* CSS Variables for Design Tokens */
:root {
  --color-base: #0F172A;           /* Deep obsidian dark mode */
  --color-smoke-reflection: #E2E8F0; /* Primary Headers */
  --color-white-glint: #F8FAFC;    /* Main Metrics */
  --color-silver-mist: #94A3B8;    /* Secondary Metrics */
  --color-goldenrod-core: #DAA520; /* Critical Alerts */
  --color-emerald-signal: #10B981; /* Emerald Signal */
  --color-ruby-signal: #EF4444;    /* Ruby Signal */
  --color-wire: rgba(148,163,184,0.1); /* Translucent wire color */
}

/* Base styles */
html, body {
  height: 100%;
  margin: 0;
  padding: 0;
  background-color: var(--color-base);
  color: var(--color-white-glint);
  font-family: 'JetBrains Mono', 'Roboto Mono', monospace;
  font-size: 16px;
}

/* Link styling */
a {
  color: var(--color-white-glint);
  text-decoration: underline;
}
a:hover {
  color: var(--color-emerald-signal);
}

/* Utility classes for specific uses */
.bg-base {
  background-color: var(--color-base);
}
.text-smoke-reflection {
  color: var(--color-smoke-reflection);
}
.text-white-glint {
  color: var(--color-white-glint);
}
.text-silver-mist {
  color: var(--color-silver-mist);
}
.text-goldenrod-core {
  color: var(--color-goldenrod-core);
}
.text-emerald-signal {
  color: var(--color-emerald-signal);
}
.text-ruby-signal {
  color: var(--color-ruby-signal);
}

/* Under-glass container fills */
.bg-emerald-glass {
  background-color: rgba(16,185,129,0.1);
}
.bg-ruby-glass {
  background-color: rgba(239,68,68,0.1);
}
.bg-goldenrod-glass {
  background-color: rgba(218,165,32,0.05);
}

/* Divider / grid line */
.divider-wire {
  border-color: var(--color-wire);
}

/* Ensure images max width */
img {
  max-width: 100%;
  height: auto;
}

