import type { Metadata } from 'next';
import { JetBrains_Mono } from 'next/font/google';

const mono = JetBrains_Mono({ subsets: ['latin'] });

export const metadata: Metadata = {
  title: 'Nerve Center - Rhythm High Finance',
  description: 'The central dashboard for monitoring and orchestrating Warlord WASP operations.',
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en" className="h-full">
      <body className={`${mono.className} h-full bg-obsidian text-white-glint antialiased`}>
        {children}
      </body>
    </html>
  );
}

@tailwind base;
@tailwind components;
@tailwind utilities;

module.exports = {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  }
}

import type { Config } from "tailwindcss";

const config: Config = {
 content: [
 "./src/pages/**/*.{js,ts,jsx,tsx,mdx}",
 "./src/components/**/*.{js,ts,jsx,tsx,mdx}",
 "./src/app/**/*.{js,ts,jsx,tsx,mdx}",
 ],
 theme: {
 extend: {
 colors: {
 rhythm: {
 obsidian: "#0A0C10",
 charcoal: "#12161F",
 goldenrod: "#DAA520",
 silver: "#A0AEC0",
 },
 },
 },
 },
 plugins: [],
};

export default config;

@tailwind base;
@tailwind components;
@tailwind utilities;

