 ],
 theme: {
 extend: {
 colors: {
 rhythm: {
 obsidian: "#0A0C10",
 charcoal: "#12161F",
 goldenrod: "#DAA520",
 silver: "#A0AEC0",
 },
 },
 },
 },
 plugins: [],
};

export default config;

